CREATE POLICY expenses_select ON public.expenses FOR SELECT TO authenticated USING (organization_id IN (SELECT organization_id FROM public.user_roles WHERE user_id = auth.uid())); CREATE POLICY expenses_insert ON public.expenses FOR INSERT TO authenticated WITH CHECK (organization_id IN (SELECT organization_id FROM public.user_roles WHERE user_id = auth.uid()) AND created_by = auth.uid()); CREATE POLICY expenses_update ON public.expenses FOR UPDATE TO authenticated USING (organization_id IN (SELECT organization_id FROM public.user_roles WHERE user_id = auth.uid())) WITH CHECK (organization_id IN (SELECT organization_id FROM public.user_roles WHERE user_id = auth.uid())); CREATE POLICY expenses_delete ON public.expenses FOR DELETE TO authenticated USING (organization_id IN (SELECT organization_id FROM public.user_roles WHERE user_id = auth.uid()));